describe('Notification Count Reset', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="notification-icon"]').should('be.visible');
  });

  it('should reset notification count to zero after reading all messages', () => {
    // Verify initial notification count is greater than zero
    cy.get('[data-testid="notification-badge"]')
      .should('be.visible')
      .and('contain', '3');

    // Click notification icon to open notification panel
    cy.get('[data-testid="notification-icon"]').click();

    // Verify notification panel is displayed
    cy.get('[data-testid="notification-panel"]').should('be.visible');

    // Read all messages by clicking on each notification
    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).click();
      cy.get('[data-testid="message-content"]').should('be.visible');
    });

    // Close notification panel
    cy.get('[data-testid="notification-panel-close"]').click();

    // Verify notification count is reset to zero
    cy.get('[data-testid="notification-badge"]')
      .should('be.visible')
      .and('contain', '0');
  });

  it('should handle edge case when no notifications exist', () => {
    // Verify notification badge shows zero when no messages
    cy.get('[data-testid="notification-badge"]')
      .should('be.visible')
      .and('contain', '0');

    // Click notification icon
    cy.get('[data-testid="notification-icon"]').click();

    // Verify empty state message is displayed
    cy.get('[data-testid="notification-panel"]').should('be.visible');
    cy.get('[data-testid="empty-notification-message"]')
      .should('be.visible')
      .and('contain', 'No new messages');

    // Close panel
    cy.get('[data-testid="notification-panel-close"]').click();

    // Verify badge still shows zero
    cy.get('[data-testid="notification-badge"]')
      .should('contain', '0');
  });

  it('should reset count only after all messages are read', () => {
    // Verify initial count
    cy.get('[data-testid="notification-badge"]')
      .should('contain', '2');

    // Open notification panel
    cy.get('[data-testid="notification-icon"]').click();

    // Read only first message
    cy.get('[data-testid="notification-item"]').first().click();
    cy.get('[data-testid="message-content"]').should('be.visible');

    // Close panel
    cy.get('[data-testid="notification-panel-close"]').click();

    // Verify count is still 1 (not reset yet)
    cy.get('[data-testid="notification-badge"]')
      .should('contain', '1');

    // Open panel again and read remaining message
    cy.get('[data-testid="notification-icon"]').click();
    cy.get('[data-testid="notification-item"]').click();

    // Close panel
    cy.get('[data-testid="notification-panel-close"]').click();

    // Verify count is now reset to zero
    cy.get('[data-testid="notification-badge"]')
      .should('contain', '0');
  });
});
